/* Presentation adapter for the original Yii transaction grid.
   Keeps filter controls, field names and sorting links intact. */
(function () {
    'use strict';

    var TABLE_SELECTOR = '.balance-grid-view'; // Original server-rendered grid.
    var ORIGINAL_COLUMN_COUNT = 9; // Guard against an incompatible backend layout.
    var COLUMN_KEYS = ['id', 'user', 'code', 'amount', 'before', 'service', 'date', 'type', 'description'];
    var EXPERT_FILTER_NAME = 'BalanceTransactionSearch[expert_id]'; // Proposed backend filter; disabled until integrated.
    var DEMO_BALANCES_ENABLED = !!document.querySelector('script[src="assets/preview-only.js"]');
    var CREDIT_SCALE = 100n; // Sum credits in hundredths to avoid floating-point errors.

    function decimalUnits(value, decimals, signed) {
        var pattern = new RegExp('^' + (signed ? '-?' : '') + '\\d{1,32}(?:\\.\\d{1,' + decimals + '})?$');
        if (typeof value !== 'string' || !pattern.test(value)) return null;
        var parts = value.replace('-', '').split('.');
        var units = BigInt(parts[0]) * (10n ** BigInt(decimals)) + BigInt((parts[1] || '').padEnd(decimals, '0'));
        return value.startsWith('-') ? -units : units;
    }
    function fixedCredits(units) {
        return (units / 100n).toString() + '.' + (units % 100n).toString().padStart(2, '0');
    }
    function payoutSnapshot(header) {
        if (!header) return { availability: 'unknown' };
        if (header.getAttribute('data-payout-pending') === 'true') return { availability: 'pending' };
        if (header.getAttribute('data-payout-can-request') !== 'true') return { availability: 'denied' };
        var balance = decimalUnits(header.getAttribute('data-current-balance'), 2, true);
        if (balance === null) return { availability: 'unknown' };
        if (balance <= 0n) return { availability: 'nonpositive' };
        var minimum = decimalUnits(header.getAttribute('data-payout-minimum-credits'), 2, false);
        var rateText = header.getAttribute('data-payout-usd-per-credit');
        var rate = decimalUnits(rateText, 12, false);
        if (minimum === null || minimum <= 0n || rate === null || rate <= 0n) return { availability: 'settings_unknown' };
        // Display only: positive integer division rounds down once to USD cents.
        var usdCents = balance * rate / 1000000000000n;
        return { availability: balance < minimum ? 'below_minimum' : usdCents <= 0n ? 'amount_zero' : 'available',
            minimum: fixedCredits(minimum), rate: rateText, amountUsd: fixedCredits(usdCents) };
    }
    function payoutAvailability(header) { return payoutSnapshot(header).availability; }
    function payoutMessage(snapshot) {
        if (snapshot.availability === 'pending') return 'Заявка ожидает обработки. Повторная отправка недоступна.';
        if (snapshot.availability === 'denied') return 'Право на собственную выплату в админке не подтверждено.';
        if (snapshot.availability === 'nonpositive') return 'Для выплаты нужен положительный доступный баланс.';
        if (snapshot.availability === 'unknown') return 'Доступный баланс не получен.';
        if (snapshot.availability === 'settings_unknown') return 'Настройки курса и минимального остатка не получены или некорректны.';
        if (snapshot.availability === 'below_minimum') return 'Минимум для заявки: ' + snapshot.minimum + ' кредитов.';
        if (snapshot.availability === 'amount_zero') return 'Рассчитанная сумма выплаты должна быть положительной.';
        return 'Заявка на весь доступный баланс. Курс и сумма фиксируются при создании; комиссия компании не вычитается.';
    }

    function initPayoutModal() {
        if (document.getElementById('balancePayoutModal')) return;
        var modal = document.createElement('div');
        modal.id = 'balancePayoutModal';
        modal.className = 'modal fade balance-payout-modal';
        modal.tabIndex = -1;
        modal.setAttribute('role', 'dialog');
        modal.setAttribute('aria-modal', 'true');
        modal.setAttribute('aria-labelledby', 'balancePayoutTitle');
        modal.innerHTML = '<div class="modal-dialog" role="document"><div class="modal-content">' +
            '<div class="modal-header"><button type="button" class="close" data-dismiss="modal" aria-label="Закрыть">' +
            '<span aria-hidden="true">&times;</span></button><h4 class="modal-title" id="balancePayoutTitle">Заказать выплату?</h4></div>' +
            '<div class="modal-body"><div class="balance-payout-summary"><span>Текущий баланс, кредиты</span>' +
            '<strong class="js-payout-current-balance"></strong></div>' +
            '<p class="js-payout-calculation"></p>' +
            '<p class="js-payout-status" role="status"></p></div>' +
            '<div class="modal-footer"><button type="button" class="btn btn-default" data-dismiss="modal">Отмена</button>' +
            '<button type="button" class="btn btn-primary js-confirm-payout" disabled>' +
            (DEMO_BALANCES_ENABLED ? 'Проверить заявку' : 'Подтвердить') + '</button></div></div></div>';
        document.body.appendChild(modal);
        modal.addEventListener('keydown', function (event) {
            if (event.key !== 'Tab' || !modal.classList.contains('in')) return;
            var focusable = Array.from(modal.querySelectorAll('button, [href], input, select, textarea, [tabindex]'))
                .filter(function (element) {
                    return !element.disabled && element.tabIndex >= 0 && element.getClientRects().length > 0 &&
                        window.getComputedStyle(element).visibility === 'visible';
                });
            var first = focusable[0];
            var last = focusable[focusable.length - 1];
            // Bootstrap restores focus on close; contain Tab inside the open dialog.
            if (!first || !focusable.includes(document.activeElement) ||
                (event.shiftKey ? document.activeElement === first : document.activeElement === last)) {
                event.preventDefault();
                (event.shiftKey ? last || modal : first || modal).focus();
            }
        });
        var confirm = modal.querySelector('.js-confirm-payout');
        window.jQuery(modal).on('show.bs.modal', function () {
            var value = document.querySelector('.balance-header-actions .balance-current-value');
            modal.querySelector('.js-payout-current-balance').textContent = value ? value.textContent : '—';
            var header = document.querySelector('.balance-page-header');
            var snapshot = payoutSnapshot(header);
            confirm.disabled = !DEMO_BALANCES_ENABLED || snapshot.availability !== 'available';
            modal.querySelector('.js-payout-calculation').textContent = snapshot.amountUsd
                ? 'Получателю: ' + snapshot.amountUsd + ' USD · Курс: ' + snapshot.rate + ' USD за кредит · Округление вниз.' : '';
            modal.querySelector('.js-payout-status').textContent = payoutMessage(snapshot);
        });
        confirm.addEventListener('click', function () {
            if (confirm.disabled || !DEMO_BALANCES_ENABLED) return;
            if (document.activeElement === confirm) modal.querySelector('.modal-footer [data-dismiss="modal"]').focus();
            confirm.disabled = true;
            var header = document.querySelector('.balance-page-header');
            if (payoutAvailability(header) !== 'available') {
                modal.querySelector('.js-payout-status').textContent = 'Заявка недоступна. Проверьте текущий остаток и статус заявки.';
                return;
            }
            // Preview validation cannot invoke the legacy payout handler or debit a wallet.
            modal.querySelector('.js-payout-status').textContent =
                'Демо: заявка проверена. Запрос не отправлен, кредиты не списаны. Сервер повторно проверяет право, остаток, минимум и курс.';
        });
    }

    function creditUnits(cell) {
        if (!cell) return null;
        var raw = cell.getAttribute('data-credit-amount');
        if (raw === null) raw = cell.textContent;
        var match = raw.replace(/\s/g, '').replace(/\u2212/g, '-').match(/^([+-]?)(\d+)(?:[.,](\d{1,2}))?$/);
        if (!match) return null;
        var units = BigInt(match[2]) * CREDIT_SCALE + BigInt((match[3] || '').padEnd(2, '0'));
        return match[1] === '-' ? -units : units;
    }

    function formatCredits(units) {
        var magnitude = units < 0n ? -units : units;
        return (units < 0n ? '−' : units > 0n ? '+' : '') +
            (magnitude / CREDIT_SCALE).toLocaleString('ru-RU') + ',' +
            String(magnitude % CREDIT_SCALE).padStart(2, '0');
    }

    function updateSelectionSummary(table) {
        var summary = table.parentElement.querySelector(':scope > .summary');
        if (!summary) return;
        if (!summary.querySelector('.balance-range-summary')) {
            var range = document.createElement('span');
            range.className = 'balance-range-summary';
            while (summary.firstChild) range.appendChild(summary.firstChild);
            var result = document.createElement('span');
            result.className = 'balance-selection-summary';
            result.setAttribute('role', 'status');
            result.setAttribute('aria-live', 'polite');
            result.setAttribute('aria-atomic', 'true');
            summary.append(range, result);
            summary.classList.add('balance-summary');
        }
        var selected = Array.from(table.querySelectorAll('tbody .grid-row-check:checked'));
        var total = 0n;
        var invalid = false;
        selected.forEach(function (box) {
            var units = creditUnits(box.closest('tr').querySelector('.balance-col-amount'));
            if (units === null) invalid = true;
            else total += units;
        });
        summary.querySelector('.balance-range-summary').hidden = selected.length > 0;
        var output = summary.querySelector('.balance-selection-summary');
        output.textContent = selected.length ? 'Выбрано: ' + selected.length + ' · ' +
            (invalid ? 'Сумма недоступна: проверьте значения' : 'Сумма выбранных операций: ' + formatCredits(total) + ' кредитов') : '';
        output.title = output.textContent;
        output.classList.toggle('has-error', invalid);
    }

    function expertCell(row, isHeading, isFilter, partyRole) {
        var cell = document.createElement(isHeading ? 'th' : 'td');
        cell.className = 'balance-col-expert';
        if (isHeading) {
            cell.scope = 'col';
            cell.textContent = 'Эксперт';
        } else if (isFilter) {
            var select = document.createElement('select');
            select.className = 'form-control';
            select.name = EXPERT_FILTER_NAME;
            select.disabled = row.closest('table').getAttribute('data-party-filters-ready') !== 'true';
            select.setAttribute('aria-label', 'Эксперт' + (select.disabled ? ': фильтр пока не подключён' : ''));
            select.title = select.disabled ? 'Фильтр эксперта пока не подключён' : 'Эксперт';
            var option = document.createElement('option');
            option.value = '';
            option.textContent = 'Эксперт';
            select.appendChild(option);
            cell.appendChild(select);
        } else {
            // The original snapshot has no expert relation. Never infer it from the user.
            var role = partyRole || 'expert';
            var name = row.getAttribute('data-' + role + '-name');
            var username = row.getAttribute('data-' + role + '-username');
            if (!name && !username) {
                cell.textContent = '—';
                cell.classList.add('text-muted');
            } else {
                var person = document.createElement('div');
                person.className = 'user-column';
                var info = document.createElement('div');
                info.className = 'user-info';
                var label = document.createElement('div');
                label.className = 'name';
                label.textContent = name || username;
                info.appendChild(label);
                if (name && username) {
                    var login = document.createElement('div');
                    login.className = 'username';
                    login.textContent = username;
                    info.appendChild(login);
                }
                person.appendChild(info);
                cell.appendChild(person);
            }
        }
        return cell;
    }

    function enhanceBalance() {
        document.querySelectorAll(TABLE_SELECTOR).forEach(function (table) {
            var heading = document.querySelector('.content-header h1');
            if (heading) heading.textContent = 'Мой баланс';
            document.title = 'Мой баланс';
            if (heading) {
                var header = heading.closest('.content-header');
                header.classList.add('balance-page-header');
                if (!header.querySelector('.js-request-payout')) {
                    var payout = document.createElement('button');
                    payout.type = 'button';
                    payout.className = 'btn btn-primary btn-sm balance-payout-button js-request-payout';
                    payout.textContent = 'Заказать выплату';
                    payout.setAttribute('data-toggle', 'modal');
                    payout.setAttribute('data-target', '#balancePayoutModal');
                    payout.setAttribute('aria-haspopup', 'dialog');
                    payout.disabled = true;
                    header.appendChild(payout);
                }
                initPayoutModal();
                var ownerName = header.getAttribute('data-owner-name');
                if (ownerName && !header.querySelector('.balance-owner-context')) {
                    var ownerContext = document.createElement('span');
                    ownerContext.className = 'balance-owner-context';
                    ownerContext.textContent = 'Владелец: ' + ownerName;
                    header.appendChild(ownerContext);
                }
                var actions = header.querySelector('.balance-header-actions');
                if (!actions) {
                    actions = document.createElement('div');
                    actions.className = 'balance-header-actions';
                    var currentBalance = document.createElement('span');
                    currentBalance.className = 'balance-current-value';
                    actions.appendChild(currentBalance);
                    actions.appendChild(header.querySelector('.js-request-payout'));
                    header.appendChild(actions);
                }
                // Render the authenticated user's server balance, never a sum of grid rows.
                var rawBalance = header.getAttribute('data-current-balance') || '';
                var validBalance = /^-?\d+(\.\d{1,2})?$/.test(rawBalance) && Number.isFinite(Number(rawBalance));
                var balanceLabel = validBalance
                    ? Number(rawBalance).toLocaleString('ru-RU', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' кредитов'
                    : '—';
                var balanceValue = actions.querySelector('.balance-current-value');
                balanceValue.textContent = balanceLabel;
                balanceValue.setAttribute('aria-label', 'Текущий баланс, кредиты: ' + balanceLabel);
                balanceValue.title = header.getAttribute('data-balance-demo') === 'true'
                    ? 'Текущий баланс: демонстрационное значение'
                    : 'Текущий баланс';
                var payoutButton = header.querySelector('.js-request-payout');
                var payoutState = payoutSnapshot(header);
                payoutButton.disabled = !DEMO_BALANCES_ENABLED || payoutState.availability !== 'available';
                payoutButton.title = payoutState.availability !== 'available' ? payoutMessage(payoutState)
                    : DEMO_BALANCES_ENABLED ? 'Проверить заявку без отправки' : 'Серверный адаптер выплаты не подключён';
                var eligibility = actions.querySelector('.balance-payout-eligibility');
                if (!eligibility) {
                    eligibility = document.createElement('span');
                    eligibility.className = 'balance-payout-eligibility text-muted';
                    eligibility.setAttribute('role', 'status');
                    actions.appendChild(eligibility);
                }
                eligibility.textContent = payoutState.minimum
                    ? 'Минимум: ' + payoutState.minimum + ' кредитов · Курс: ' + payoutState.rate + ' USD за кредит'
                    : payoutMessage(payoutState);
            }

            Array.from(table.rows).forEach(function (row) {
                if (row.dataset.balanceEnhanced) return;
                var cells = Array.from(row.cells).filter(function (cell) {
                    return !cell.classList.contains('grid-select-cell');
                });
                // Yii renders an empty-state row with one spanning cell.
                if (cells.length === 1 && cells[0].colSpan === ORIGINAL_COLUMN_COUNT) {
                    cells[0].colSpan = ORIGINAL_COLUMN_COUNT - 1;
                    row.dataset.balanceEnhanced = 'true';
                    return;
                }
                if (cells.length !== ORIGINAL_COLUMN_COUNT) return;

                cells.forEach(function (cell, index) {
                    cell.classList.add('balance-col-' + COLUMN_KEYS[index]);
                });
                row.insertBefore(cells[2], cells[1]);
                var isFilter = row.classList.contains('filters');
                var isHeading = row.parentElement === table.tHead && !isFilter;
                row.insertBefore(expertCell(row, isHeading, isFilter), cells[1]);
                cells[5].remove();

                if (isHeading) {
                    if (table.getAttribute('data-party-projection') === 'true') {
                        // The inherited user_id sort belongs to the wallet owner, not to the client.
                        cells[1].textContent = 'Клиент';
                    } else {
                        var ownerLabel = cells[1].querySelector('a') || cells[1];
                        ownerLabel.textContent = 'Владелец';
                    }
                    var amountLabel = cells[3].querySelector('a') || cells[3];
                    amountLabel.textContent = 'Кредиты';
                    cells[4].textContent = 'Баланс до операции';
                    var dateLabel = cells[6].querySelector('a') || cells[6];
                    dateLabel.textContent = 'Дата';
                    var typeLabel = cells[7].querySelector('a') || cells[7];
                    typeLabel.textContent = 'Тип и описание';
                } else if (isFilter) {
                    // My Balance has an immutable owner scope; never offer a user_id owner override.
                    cells[1].replaceChildren();
                    if (table.getAttribute('data-party-projection') === 'true') {
                        var clientFilter = document.createElement('select');
                        clientFilter.className = 'form-control';
                        clientFilter.name = 'BalanceTransactionSearch[client_id]';
                        clientFilter.setAttribute('aria-label', 'Клиент');
                        clientFilter.disabled = table.getAttribute('data-party-filters-ready') !== 'true';
                        clientFilter.appendChild(new Option('', ''));
                        cells[1].appendChild(clientFilter);
                    }
                } else if (row.parentElement.tagName === 'TBODY') {
                    if (table.getAttribute('data-party-projection') === 'true') {
                        var client = expertCell(row, false, false, 'client');
                        cells[1].replaceChildren(...client.childNodes);
                    }
                    var amountText = document.createTreeWalker(cells[3], NodeFilter.SHOW_TEXT);
                    var textNode;
                    while ((textNode = amountText.nextNode())) {
                        textNode.nodeValue = textNode.nodeValue.replace(/\s*кредит(?:ов|а|ы)?/gi, '');
                    }
                    if (creditUnits(cells[4]) === null) cells[4].textContent = '—';
                    cells[4].title = 'Баланс владельца до этой операции';
                    var content = document.createElement('div');
                    content.className = 'balance-description';
                    var description = document.createElement('span');
                    description.className = 'balance-description-text';
                    // Move, never clone: preserve links, icons and attached handlers.
                    while (cells[7].firstChild) content.appendChild(cells[7].firstChild);
                    while (cells[8].firstChild) description.appendChild(cells[8].firstChild);
                    content.appendChild(description);
                    cells[7].appendChild(content);
                }
                cells[8].remove();
                row.dataset.balanceEnhanced = 'true';
            });
            updateSelectionSummary(table);
        });
    }

    document.addEventListener('admin:selectionchange', function (event) {
        if (event.target.matches(TABLE_SELECTOR)) updateSelectionSummary(event.target);
    });

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', enhanceBalance);
    } else {
        enhanceBalance();
    }
    // Reapply after Yii/PJAX replaces grid rows; repeated calls are safe.
    if (window.jQuery) {
        window.jQuery(document).on('pjax:end.balancePresentation', enhanceBalance);
    }
}());

/* Select2 options are loaded only by the static preview. */
(function () {
    if (!document.querySelector('script[src="assets/preview-only.js"]')) return;
    var demo = document.createElement('script');
    demo.src = new URL('balance_demo.js', document.currentScript.src).href;
    document.head.appendChild(demo);
}());

