/* Shared, page-scoped selection. No requests or business actions. */
(function () {
    'use strict';
    if (window.AdminTableSelection) return;
    var TABLE_SELECTOR = '.content table.table'; // Only record tables with a header are enhanced.

    function boxes(table) {
        return Array.from(table.querySelectorAll('tbody .grid-row-check'));
    }

    function getSelectedIds(table) {
        return boxes(table).filter(function (box) { return box.checked; })
            .map(function (box) { return box.value; });
    }

    function sync(table, notify) {
        var rows = boxes(table);
        var active = rows.filter(function (box) {
            return !box.disabled && !box.closest('tr').hidden && box.closest('tr').getClientRects().length;
        });
        var selected = active.filter(function (box) { return box.checked; }).length;
        var all = table.querySelector('.grid-check-all');
        if (all) {
            all.checked = active.length > 0 && selected === active.length;
            all.indeterminate = selected > 0 && selected < active.length;
            all.disabled = active.length === 0;
        }
        rows.forEach(function (box) {
            box.closest('tr').classList.toggle('grid-row-selected', box.checked);
        });
        if (notify) table.dispatchEvent(new CustomEvent('admin:selectionchange', {
            bubbles: true,
            detail: { ids: getSelectedIds(table), scope: 'current-page' }
        }));
    }

    function checkbox(label, className) {
        var input = document.createElement('input');
        input.type = 'checkbox';
        input.className = className;
        input.setAttribute('aria-label', label);
        return input;
    }

    function init() {
        document.querySelectorAll(TABLE_SELECTOR).forEach(function (table) {
            if (!table.tHead || !table.tBodies.length) return;
            // Do not add a competing selection mechanism to a native Yii CheckboxColumn.
            if (!table.classList.contains('grid-selectable') && table.querySelector('input[type="checkbox"]')) return;
            table.classList.add('grid-selectable');
            var colgroup = table.querySelector('colgroup');
            if (colgroup && !colgroup.querySelector('.grid-select-col')) {
                var col = document.createElement('col');
                col.className = 'grid-select-col';
                col.style.width = '38px';
                colgroup.prepend(col);
            }
            Array.from(table.tHead.rows).forEach(function (row, index) {
                if (row.querySelector('.grid-select-cell')) return;
                var cell = document.createElement(index === 0 ? 'th' : 'td');
                cell.className = 'grid-select-cell';
                if (index === 0) {
                    cell.scope = 'col';
                    cell.appendChild(checkbox('Выбрать все строки на этой странице', 'grid-check-all'));
                }
                row.prepend(cell);
            });
            Array.from(table.tBodies).forEach(function (body) {
                Array.from(body.rows).forEach(function (row) {
                    if (row.querySelector('.grid-select-cell')) return;
                    if (row.cells.length === 1 && row.cells[0].colSpan > 1) {
                        row.cells[0].colSpan = table.tHead.rows[0].cells.length;
                        return;
                    }
                    var id = row.getAttribute('data-key');
                    // Refund history has a displayed numeric ID, but no data-key.
                    if (id === null && row.cells[0]) {
                        var match = row.cells[0].textContent.trim().match(/^#?(\d+)$/);
                        if (match) id = match[1];
                    }
                    var cell = document.createElement('td');
                    cell.className = 'grid-select-cell';
                    if (id !== null) {
                        var input = checkbox('Выбрать запись ' + id, 'grid-row-check');
                        input.value = id;
                        cell.appendChild(input);
                    }
                    row.prepend(cell);
                });
            });
            if (!table.dataset.gridSelectionBound) {
                table.addEventListener('change', function (event) {
                    if (event.target.matches('.grid-check-all')) {
                        boxes(table).forEach(function (box) {
                            if (!box.disabled && !box.closest('tr').hidden && box.closest('tr').getClientRects().length) {
                                box.checked = event.target.checked;
                            }
                        });
                    } else if (!event.target.matches('.grid-row-check')) return;
                    sync(table, true);
                });
                table.dataset.gridSelectionBound = 'true';
            }
            sync(table, false);
        });
    }

    window.AdminTableSelection = { init: init, getSelectedIds: getSelectedIds };
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
    else init();
    if (window.jQuery) window.jQuery(document).on('pjax:end.tableSelection', init);
}());

